nextflow_process {

    name "Test Process MERQURYFK"
    script "../main.nf"
    process "MERQURYFK_MERQURYFK"

    tag "modules"
    tag "modules_nfcore"
    tag "merquryfk"
    tag "merquryfk/merquryfk"
    tag "merquryfk/hapmaker"
    tag "fastk"
    tag "fastk/fastk"

    setup {
        run("FASTK_FASTK") {
            script "../../../fastk/fastk"
            process {
                """
                input[0] = [
                    [ id:'test', single_end:false ],
                    file(params.modules_testdata_base_path + 'delete_me/merquryfk/Child.Reads.fasta.gz', checkIfExists: true)
                ]
                """
            }
        }

        run("FASTK_FASTK", alias: "FASTK_MAT") {
            script "../../../fastk/fastk"
            process {
                """
                input[0] = [
                    [ id:'test_mat', single_end:false ],
                    file(params.modules_testdata_base_path + 'delete_me/merquryfk/Mother.Reads.fasta.gz', checkIfExists: true),
                ]
                """
            }
        }

        run("FASTK_FASTK", alias: "FASTK_PAT") {
            script "../../../fastk/fastk"
            process {
                """
                input[0] = [
                    [ id:'test_pat', single_end:false ],
                    file(params.modules_testdata_base_path + 'delete_me/merquryfk/Father.Reads.fasta.gz', checkIfExists: true),
                ]
                """
            }
        }

        run("MERQURYFK_HAPMAKER") {
            script "../../hapmaker"
            process {
                """
                input[0] = FASTK_MAT.out.ktab
                input[1] = FASTK_PAT.out.ktab
                input[2] = FASTK_FASTK.out.ktab
                """
            }
        }
    }

    test("MerquryFK - Synthetic trio data - hap1 only - no trio") {

        config "./nextflow.config"

        when {
            process {
                """
                input[0] = FASTK_FASTK.out.hist.join(FASTK_FASTK.out.ktab).map { meta, hist, ktab ->
                        [ meta, hist, ktab, file(params.modules_testdata_base_path + 'delete_me/merquryfk/Hap1.fasta.gz', checkIfExists: true), [] ]
                    }
                input[1] = [[:], []]
                input[2] = [[:], []]
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert snapshot(
                    process.out.stats,
                    process.out.qv,
                    process.out.assembly_qv,
                    process.out.images.collect { meta, images -> [ meta, images.collect { img -> file(img).name } ] },
                    process.out.findAll { key, val -> key.startsWith("versions")}
                ).match() }
            )
        }

    }

    test("MerquryFK - Synthetic trio data - both haps - no trio") {

        config "./nextflow.config"

        when {
            process {
                """
                input[0] = FASTK_FASTK.out.hist.join(FASTK_FASTK.out.ktab).map { meta, hist, ktab ->
                        [
                            meta,
                            hist,
                            ktab,
                            file(params.modules_testdata_base_path + 'delete_me/merquryfk/Hap1.fasta.gz', checkIfExists: true),
                            file(params.modules_testdata_base_path + 'delete_me/merquryfk/Hap2.fasta.gz', checkIfExists: true),
                        ]
                    }
                input[1] = [[:], []]
                input[2] = [[:], []]
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert snapshot(
                    process.out.stats,
                    process.out.qv,
                    process.out.assembly_qv,
                    process.out.images.collect { meta, images -> [ meta, images.collect { img -> file(img).name } ] },
                    process.out.findAll { key, val -> key.startsWith("versions")}
                ).match() }
            )
        }

    }

    test("MerquryFK - Synthetic trio data - multiple haps - no trio") {

        config "./nextflow.config"

        when {
            process {
                """
                input[0] = FASTK_FASTK.out.hist.join(FASTK_FASTK.out.ktab).map { meta, hist, ktab ->
                        [
                            meta,
                            hist,
                            ktab,
                            file(params.modules_testdata_base_path + 'delete_me/merquryfk/Hap1.fasta.gz', checkIfExists: true),
                            [
                                file(params.modules_testdata_base_path + 'delete_me/merquryfk/Hap2.fasta.gz', checkIfExists: true),
                                file(params.modules_testdata_base_path + 'genomics/eukaryotes/Pipistrellus_nathusii/genome/test.fasta.gz', checkIfExists: true),
                            ]
                        ]
                    }
                input[1] = [[:], []]
                input[2] = [[:], []]
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert snapshot(
                    process.out.stats,
                    process.out.qv,
                    process.out.assembly_qv,
                    process.out.images.collect { meta, images -> [ meta, images.collect { img -> file(img).name } ] },
                    process.out.findAll { key, val -> key.startsWith("versions")}
                ).match() }
            )
        }

    }

    test("MerquryFK - Synthetic trio data - both haps - trio") {

        config "./nextflow.config"

        when {

            process {
                """
                input[0] = FASTK_FASTK.out.hist.join(FASTK_FASTK.out.ktab).map { meta, hist, ktab ->
                        [
                            meta,
                            hist,
                            ktab,
                            file(params.modules_testdata_base_path + 'delete_me/merquryfk/Hap1.fasta.gz', checkIfExists: true),
                            file(params.modules_testdata_base_path + 'delete_me/merquryfk/Hap2.fasta.gz', checkIfExists: true),
                        ]
                    }
                input[1] = MERQURYFK_HAPMAKER.out.mat_hap_ktab
                input[2] = MERQURYFK_HAPMAKER.out.pat_hap_ktab
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert snapshot(
                    process.out.stats,
                    process.out.qv,
                    process.out.assembly_qv,
                    process.out.phased_block_bed,
                    process.out.phased_block_stats,
                    process.out.images.collect { meta, images -> [ meta, images.collect { img -> file(img).name } ] },
                    process.out.findAll { key, val -> key.startsWith("versions")}
                ).match() }
            )
        }

    }

    test("homo_sapiens - Illumina - stub") {

        options "-stub"
        config "./nextflow.config"

        when {
            process {
                """
                input[0] = FASTK_FASTK.out.hist.join(FASTK_FASTK.out.ktab).map { meta, hist, ktab ->
                        [
                            meta,
                            hist,
                            ktab,
                            file(params.modules_testdata_base_path + 'delete_me/merquryfk/Hap1.fasta.gz', checkIfExists: true),
                            file(params.modules_testdata_base_path + 'delete_me/merquryfk/Hap2.fasta.gz', checkIfExists: true),
                        ]
                    }
                input[1] = [[:], []]
                input[2] = [[:], []]
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert snapshot(process.out).match() }
            )
        }

    }

}

